"""Declarative base, naming conventions and reusable column mixins."""

from __future__ import annotations

import datetime as dt
import uuid

from sqlalchemy import MetaData, String, func
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

from api_framework.db.types import UtcDateTime

# Deterministic constraint names.
#
# Two reasons this is not optional:
#  1. Without it the backend invents names, so an autogenerated Alembic
#     migration cannot reliably DROP a constraint it did not name.
#  2. SQLite cannot ALTER a constraint at all - Alembic emulates it by
#     rebuilding the table ("batch mode"), which requires every constraint to
#     have a known name. Skip this and batch migrations fail on unnamed keys.
NAMING_CONVENTION = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    """Base class for all ORM models.

    Alembic's `target_metadata` points at `Base.metadata`, so a model is only
    visible to autogenerate if its module is imported before Alembic runs -
    see `db/models.py`.
    """

    metadata = MetaData(naming_convention=NAMING_CONVENTION)


def utc_now() -> dt.datetime:
    """Timezone-aware UTC timestamp.

    `datetime.utcnow()` is deprecated in 3.12 and returns a *naive* datetime,
    which silently compares wrongly against aware ones. Always store UTC.
    """
    return dt.datetime.now(dt.UTC)


def new_uuid() -> str:
    return str(uuid.uuid4())


class UUIDPrimaryKeyMixin:
    """String UUID primary key.

    Chosen over an autoincrement integer because ids are exposed in URLs:
    sequential integers leak row counts and invite enumeration. Stored as a
    36-char string so the same DDL works on SQLite and PostgreSQL; on
    Postgres-only deployments switch to the native `UUID` type.
    """

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_uuid)


class TimestampMixin:
    """`created_at` / `updated_at`, maintained by the database.

    `server_default=func.now()` and `onupdate` keep the values correct even for
    writes that bypass the ORM (a migration, or raw SQL).
    """

    created_at: Mapped[dt.datetime] = mapped_column(
        UtcDateTime,
        nullable=False,
        default=utc_now,
        server_default=func.now(),
    )
    updated_at: Mapped[dt.datetime] = mapped_column(
        UtcDateTime,
        nullable=False,
        default=utc_now,
        server_default=func.now(),
        onupdate=utc_now,
    )
